class Gradebook:
    def __init__(self) -> None:
        self.assignments = {}  # name -> (weight, kind)
        self.grades = {}       # student -> {assignment: grade}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ("homework", "quiz"):
            raise ValueError('kind must be "homework" or "quiz"')
        self.assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if assignment not in self.assignments:
            raise KeyError(f"unknown assignment: {assignment}")
        self.grades.setdefault(student, {})[assignment] = grade

    def average(self, student: str) -> float:
        if not self.assignments:
            return 0.0

        student_grades = self.grades.get(student, {})

        # Determine drop set: lowest quiz if student has more than one quiz
        quiz_grades = [
            (grade, name)
            for name, grade in student_grades.items()
            if self.assignments[name][1] == "quiz"
        ]
        dropped = None
        if len(quiz_grades) > 1:
            dropped = min(quiz_grades)[1]

        total_weight = 0.0
        weighted_sum = 0.0
        for name, (weight, _kind) in self.assignments.items():
            if name == dropped:
                continue
            grade = student_grades.get(name, 2.0)
            weighted_sum += weight * grade
            total_weight += weight

        if total_weight == 0:
            return 0.0
        return round(weighted_sum / total_weight, 2)
